const body = $input.first().json.body ?? {};
const surface = String(body.surface ?? "").trim();

// Contrato por superficie (AssistantPanel multi-superficie) - so chega aqui
// para a superficie 'trilha' na etapa de geracao (FAQ/conteudo/fora-de-escopo
// sao resolvidos localmente no Next.js antes de proxy para o n8n) e para
// 'calendario', usada so como rotulo informativo ao lado do contrato legado.
if (surface) {
  const request = {
    surface,
    objectId: String(body.objectId ?? "").trim(),
    focus: body.focus ?? null,
    message: String(body.message ?? "").trim(),
    history: Array.isArray(body.history) ? body.history : [],
    context: body.context ?? null,
  };

  const errors = [];
  if (!["trilha", "calendario"].includes(request.surface)) {
    errors.push("surface deve ser trilha ou calendario");
  }
  if (!request.objectId) errors.push("objectId e obrigatorio");
  if (!request.message) {
    errors.push("message e obrigatoria");
  } else if (request.message.length > 4000) {
    errors.push("message deve ter no maximo 4000 caracteres");
  }

  return [
    {
      json: {
        isValid: errors.length === 0,
        errors,
        request,
        isSurfaceRequest: true,
      },
    },
  ];
}

