parameters.jsCode:
const aiOutput = $input.first().json;
const validated = $('Validate Input1').first().json;
const request = validated.request;

if (validated.isSurfaceRequest) {
  const replyText = String(aiOutput.text ?? aiOutput.output ?? aiOutput.response ?? "").trim();
  if (!replyText) {
    throw new Error("O Bedrock nao retornou uma resposta textual.");
  }
  return [
    {
      json: {
        reply: replyText,
        confidence: 0.75,
      },
    },
  ];
}

const hasStudentContext = $('Load Student Context').isExecuted;

let context = null;

if (hasStudentContext) {
  context = $('Load Student Context').first().json.data;
}

const plan = context?.suggestedPlan ?? null;

const suggestions = (plan?.suggestions ?? []).map((suggestion) => ({
  id: suggestion.id,
  title: suggestion.title,
  category: suggestion.category,
  subjectCode: suggestion.subjectCode,
  subjectName: suggestion.subjectName,
  date: suggestion.date,
  startTime: suggestion.startTime,
  endTime: suggestion.endTime,
  notes: suggestion.notes
}));

const confirmation = suggestions.length > 0
  ? {
      required: true,
      action: 'CREATE_STUDY_PLAN',
      assessmentCode: plan.assessmentCode,
      assessmentDescription: plan.assessmentDescription,
      suggestionsCount: suggestions.length,
      message: 'Confirme quais etapas deseja adicionar ao calendário.'
    }
  : null;

return [
  {
    json: {
      ok: true,
      data: {
        conversationId: request.conversationId,
        messageId: `msg-${Date.now()}`,
        agent: request.agent,
        replyText:
          aiOutput.text ??
          aiOutput.output ??
          'Não foi possível gerar uma resposta.',
        suggestions,
        confirmation
      },
      meta: {
        channel: request.channel,
        mocked: false,
        provider: 'amazon-bedrock',
        model: 'amazon.nova-micro-v1:0',
        version: 'v1'
      }
    }
  }
];

